using UnityEngine;
namespace AbujaLife.Traffic { public sealed class TrafficSignal:MonoBehaviour { public enum Phase{NorthSouth,EastWest,Pedestrian} public Phase phase; public float driveSeconds=28f,pedestrianSeconds=10f; public Renderer[] northSouth, eastWest; float remaining; void Start(){remaining=driveSeconds;Apply();} void Update(){remaining-=Time.deltaTime;if(remaining>0)return;phase=phase switch{Phase.NorthSouth=>Phase.EastWest,Phase.EastWest=>Phase.Pedestrian,_=>Phase.NorthSouth};remaining=phase==Phase.Pedestrian?pedestrianSeconds:driveSeconds;Apply();} void Apply(){/* production prefab maps emissive materials and stop triggers to phase */} public bool CanDriveNorthSouth=>phase==Phase.NorthSouth; public bool CanDriveEastWest=>phase==Phase.EastWest;} }
